// TH15 v1.00b Stage 1 MainSub00 formation (st01.ecl.txt:908-931).
// 8 left + 8 right triplets, 30 frames apart, then wait(100): one symmetric wave.
// Source chapter entry / state / -9905 gates removed per approved synthesis policy.

const TIME_LIMIT: int = 1624;      // 120 buffer + 1500 window + 4 startup
const OPENING_BUFFER: int = 120;

const TH15_BALL: int = 416;        // source type 4 -> TH15_BALL, color 6
const COLOR_6: int = 6;

// st01.ecl.txt:54-56 GirlA01_at on DIFF==3 only: etEx type 0x200000 VELTIME
// a=60, r=7.0, s=-999999 (keep current angle). Scalar speed ramps 3 -> 7 over
// 60 frames along the fired direction; target step_speed keeps the angle.
xformdef LUNATIC_SPEEDUP {
    step_speed(7fx, 60 + 65536 * EASE_LINEAR);
}

// st01.ecl.txt:8-24 GirlA01 (movement/boxes) + 375-385 GirlBlueA01e
// + 739-746 GirlRedA01. kind 0=Red (no shot), 1=Blue (shoots on N/H/L).
// mirror 1 = enmCreateM source child mirror bit: moveVel angles reflect about
// the vertical axis (67.5->112.5, 22.5->157.5 deg); firing angle is not mirrored.
async sub girl(kind: int, mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24): circular first*0.5 = 12
    set_hitbox(8fx);     // setHitbox(16,16): 16*0.5 = 8, body collision kept
    if kind == 1 && global(GVAR_RANK) >= RANK_NORMAL {
        spawn girl_attack();
    }
    // moveVel(1.1780972 rad = 67.5deg, 3.0)
    if mirror == 0 {
        move_vel(0, 12288bam, 3.0fx, EASE_LINEAR);
    } else {
        move_vel(0, 20480bam, 3.0fx, EASE_LINEAR);
    }
    wait(30);
    // moveVelTime(60, 0, 0.3926991 rad = 22.5deg, 2.0)
    if mirror == 0 {
        move_vel(60, 4096bam, 2.0fx, EASE_LINEAR);
    } else {
        move_vel(60, 28672bam, 2.0fx, EASE_LINEAR);
    }
    wait(60);
    // moveVelTime(60, 0, -999999 = keep angle, 1.0)
    move_speed(60, 1.0fx, EASE_LINEAR);
    loop { wait(1000); }   // GirlA01_256/276: keeps moving forever
}

// st01.ecl.txt:26-75 GirlA01_at. Difficulty masks are resolved against target
// rank (0=E,1=N,2=H,3=L); Easy never spawns this task.
async sub girl_attack() {
    var rank: int = global(GVAR_RANK);
    var initial: int = 90;                 // wait([-1]): E/N 90, H/L 30
    if rank >= RANK_HARD { initial = 30; }
    wait(initial);
    var speed: fx = 1.5fx;                 // etSpeed layer speed: E/N 1.5, H 2.0, L 3.0
    if rank == RANK_HARD { speed = 2.0fx; }
    if rank == RANK_LUNATIC { speed = 3.0fx; }
    var volleys: int = 1;                  // diffI($A,1,1,4,20)
    if rank == RANK_HARD { volleys = 4; }
    if rank == RANK_LUNATIC { volleys = 20; }
    var spacing: int = 30;                 // per-volley wait: E/N 30, H 20, L 5
    if rank == RANK_HARD { spacing = 20; }
    if rank == RANK_LUNATIC { spacing = 5; }
    if rank == RANK_LUNATIC {
        for i in 0..volleys {
            // etSprite(0,4,6), etAim(0,0), etCount(0,1,1): one shot aimed at player
            _ = fire(TH15_BALL, COLOR_6, $self_x, $self_y, speed, aim_player(), LUNATIC_SPEEDUP, none);
            wait(spacing);
        }
    } else {
        for j in 0..volleys {
            _ = fire(TH15_BALL, COLOR_6, $self_x, $self_y, speed, aim_player(), none, none);
            wait(spacing);
        }
    }
}

// st01.ecl.txt:908-931 MainSub00 schedule. Left triplet at A=-192:
// Red(-224,-16) Blue(-192,-28) Red(-160,-40). Right mirror triplet at A=192:
// Red(160,-40) Blue(192,-28) Red(224,-16).
async sub pattern() {
    wait(OPENING_BUFFER);
    for g in 0..8 {
        _ = spawn_enemy(-224fx, -16fx, 100, 0, 0, 0, girl(0, 0));
        _ = spawn_enemy(-192fx, -28fx, 100, 0, 0, 0, girl(1, 0));
        _ = spawn_enemy(-160fx, -40fx, 100, 0, 0, 0, girl(0, 0));
        wait(30);
    }
    for h in 0..8 {
        _ = spawn_enemy(160fx, -40fx, 100, 0, 0, 0, girl(0, 1));
        _ = spawn_enemy(192fx, -28fx, 100, 0, 0, 0, girl(1, 1));
        _ = spawn_enemy(224fx, -16fx, 100, 0, 0, 0, girl(0, 1));
        wait(30);
    }
    wait(100);
}

// Independent invincible shell: control carries the segment, real enemies keep
// their source boxes/movement/fire. Body collision on the control is disabled.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
